-- Q2: Check customer complaints for "queue too long" or similar in June 2026
SELECT kind, COUNT(*) as cnt FROM payments.customer_complaints 
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01' 
GROUP BY kind ORDER BY cnt DESC;

-- Q3: Average daily sales of toned milk over available period (check if twelve months exist)
SELECT AVG(units_sold) as avg_daily_units FROM store.daily_sales WHERE sku = 'MILK-TONED-500ML';

-- Q4: Check for any rainfall or weather-related data in the database
SELECT table_name FROM information_schema.tables WHERE table_schema NOT IN ('information_schema', 'pg_catalog') ORDER BY table_name;

-- Q5: Shelf audits in June 2026 - check statuses for "picked up and put back"
SELECT status, COUNT(*) as cnt FROM store.shelf_audits 
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01' 
GROUP BY status ORDER BY cnt DESC;

SELECT sku, name, pack, case_kg 
FROM store.products 
WHERE name ILIKE '%atta%' OR pack ILIKE '%5 kg%' OR pack ILIKE '%5kg%';

SELECT COUNT(DISTINCT DATE(audit_ts)) AS empty_days 
FROM store.shelf_audits 
WHERE sku = 'ATTA-WW-5KG' AND status = 'empty';

